(function () {
  const state = { events: [], meta: null, loading: false, error: "", filters: { from: "", to: "", type: "", origin: "", actor: "", scope: "", reference: "", result: "", search: "" }, order: "desc" };
  const escapeHtml = (value) => String(value ?? "").replace(/[&<>"']/g, (char) => ({ "&": "&amp;", "<": "&lt;", ">": "&gt;", '"': "&quot;", "'": "&#39;" }[char]));
  function session() { const value = window.CredentialsAuth?.getSession?.(); return value?.role === "superadmin" && value?.accessToken ? value : null; }
  function label(action) { return String(action || "Evento").replaceAll(".", " · ").replaceAll("_", " "); }
  function origin(item) { return item.scope === "platform" ? "sistema" : item.action.startsWith("tenant.") ? "plataforma" : item.action.startsWith("match_") || item.action.startsWith("bases_") ? "especialista tenant" : "tenant"; }
  function result(item) { const text = `${item.action} ${item.detail?.status || ""} ${item.detail?.result || ""} ${item.detail?.error || ""}`.toLowerCase(); return /failed|error|rejected|dismissed|discrepancy|abandoned/.test(text) ? "incidencia" : /pending|queued|started|review/.test(text) ? "en curso" : "correcto"; }
  function detail(item) { return Object.entries(item.detail || {}).map(([key, value]) => `${key.replaceAll("_", " ")}: ${typeof value === "object" ? JSON.stringify(value) : value}`).join(" · ") || "Sin metadatos de evidencia disponibles."; }
  function options(items, value) { return [...new Set(items.filter(Boolean))].sort((a, b) => a.localeCompare(b, "es")).map((item) => `<option value="${escapeHtml(item)}" ${value === item ? "selected" : ""}>${escapeHtml(item)}</option>`).join(""); }
  function filtered() {
    const filters = state.filters, search = filters.search.toLowerCase();
    return state.events.filter((item) => {
      const text = [label(item.action), origin(item), item.actor, item.scope, item.targetType, item.targetId, item.tenant?.name, detail(item)].join(" ").toLowerCase();
      const day = String(item.createdAt || "").slice(0, 10);
      return (!filters.from || day >= filters.from) && (!filters.to || day <= filters.to) && (!filters.type || item.targetType === filters.type)
        && (!filters.origin || origin(item) === filters.origin) && (!filters.actor || item.actor === filters.actor) && (!filters.scope || item.scope === filters.scope)
        && (!filters.reference || `${item.targetId} ${detail(item)}`.toLowerCase().includes(filters.reference.toLowerCase())) && (!filters.result || result(item) === filters.result) && (!search || text.includes(search));
    }).sort((left, right) => state.order === "asc" ? String(left.createdAt).localeCompare(String(right.createdAt)) : String(right.createdAt).localeCompare(String(left.createdAt)));
  }
  function render() {
    if (!session()) return;
    const target = document.querySelector("#audit-timeline"); if (!target) return;
    document.querySelector("#audit .panel-heading h2").textContent = "Auditoría del sistema";
    const events = filtered(), types = state.events.map((item) => item.targetType), actors = state.events.map((item) => item.actor), scopes = state.events.map((item) => item.scope), origins = state.events.map(origin);
    const controls = `<div class="audit-filter-grid"><label><span>Desde</span><input type="date" data-platform-audit-filter="from" value="${filtersValue("from")}" /></label><label><span>Hasta</span><input type="date" data-platform-audit-filter="to" value="${filtersValue("to")}" /></label><label><span>Tipo</span><select data-platform-audit-filter="type"><option value="">Todos</option>${options(types, filtersValue("type"))}</select></label><label><span>Origen</span><select data-platform-audit-filter="origin"><option value="">Todos</option>${options(origins, filtersValue("origin"))}</select></label><label><span>Actor</span><select data-platform-audit-filter="actor"><option value="">Todos</option>${options(actors, filtersValue("actor"))}</select></label><label><span>Ámbito</span><select data-platform-audit-filter="scope"><option value="">Todos</option>${options(scopes, filtersValue("scope"))}</select></label><label><span>Fuente u oportunidad</span><input data-platform-audit-filter="reference" value="${filtersValue("reference")}" placeholder="ID o URL" /></label><label><span>Resultado</span><select data-platform-audit-filter="result"><option value="">Todos</option>${options(["correcto", "en curso", "incidencia"], filtersValue("result"))}</select></label><label><span>Buscar</span><input data-platform-audit-filter="search" value="${filtersValue("search")}" placeholder="Acción o procedencia" /></label><div class="button-row"><button class="ghost-action" data-platform-audit-order type="button">${state.order === "desc" ? "Más recientes" : "Más antiguos"}</button><button class="ghost-action" data-platform-audit-export type="button">Exportar CSV</button></div></div>`;
    const rows = events.map((item) => `<div class="audit-grid-row" role="row"><time>${escapeHtml(new Date(item.createdAt).toLocaleString("es-ES", { dateStyle: "short", timeStyle: "short" }))}</time><span>${escapeHtml(item.scope === "tenant" ? item.tenant?.name || "Tenant no disponible" : "Plataforma")}</span><span>${escapeHtml(item.actor)}</span><strong>${escapeHtml(label(item.action))}</strong><span>${escapeHtml(item.targetType)} · ${escapeHtml(result(item))}</span><span><button class="text-action" data-platform-audit-detail="${escapeHtml(item.id)}" type="button">Evidencia</button>${item.tenant ? `<button class="text-action" data-platform-audit-tenant="${escapeHtml(item.tenant.id)}" type="button">Abrir entidad</button>` : ""}</span></div>`).join("");
    target.innerHTML = `${controls}<div class="plain-note"><strong>${events.length} eventos visibles</strong><span>${state.meta?.radarEventsState === "unavailable_schema" ? "Eventos técnicos del radar no disponibles: falta activar su esquema." : "Metadatos y procedencia; no se muestran contenidos privados de tenants."}</span></div>${state.loading ? '<div class="empty-state">Cargando auditoría persistida…</div>' : state.error ? `<div class="empty-state warning">${escapeHtml(state.error)}</div>` : `<div class="audit-table" role="table"><div class="audit-grid-row audit-grid-header" role="row"><span>Fecha</span><span>Ámbito auditado</span><span>Actor</span><span>Evento</span><span>Resultado</span><span>Consulta</span></div>${rows || '<div class="empty-state">Sin eventos persistidos para este periodo. La API no devolvió actividad autorizada.</div>'}</div>`}`;
  }
  function filtersValue(key) { return escapeHtml(state.filters[key] || ""); }
  async function load() {
    if (!session() || state.loading) return; state.loading = true; render();
    const dates = new URLSearchParams(); if (state.filters.from) dates.set("from", state.filters.from); if (state.filters.to) dates.set("to", state.filters.to);
    try { const response = await fetch(`/api/admin-audit-events?${dates}`, { headers: window.CredentialsAuth.authHeaders(session()) }); const payload = await response.json().catch(() => null); if (!response.ok || !payload?.ok) throw new Error(payload?.error || `Error HTTP ${response.status}`); state.events = payload.data.events || []; state.meta = payload.data; state.error = ""; }
    catch (error) { state.events = []; state.error = error.message; }
    state.loading = false; render();
  }
  function exportCsv() { const rows = filtered(); if (!rows.length) return window.showToast?.("No hay eventos para exportar."); const csv = [["Fecha", "Ámbito", "Actor", "Evento", "Tipo", "Referencia", "Resultado"], ...rows.map((item) => [item.createdAt, item.scope === "tenant" ? item.tenant?.name || "" : "Plataforma", item.actor, item.action, item.targetType, item.targetId, result(item)])].map((row) => row.map((value) => `"${String(value ?? "").replaceAll('"', '""')}"`).join(";")).join("\r\n"); const link = document.createElement("a"); link.href = URL.createObjectURL(new Blob(["\ufeff", csv], { type: "text/csv;charset=utf-8" })); link.download = `auditoria-sistema-${new Date().toISOString().slice(0, 10)}.csv`; link.click(); URL.revokeObjectURL(link.href); }
  document.addEventListener("input", (event) => { const input = event.target.closest?.("[data-platform-audit-filter]"); if (!input) return; state.filters[input.dataset.platformAuditFilter] = input.value; render(); });
  document.addEventListener("change", (event) => { const input = event.target.closest?.("[data-platform-audit-filter]"); if (!input) return; state.filters[input.dataset.platformAuditFilter] = input.value; if (["from", "to"].includes(input.dataset.platformAuditFilter)) load(); else render(); });
  document.addEventListener("click", (event) => { const detailButton = event.target.closest?.("[data-platform-audit-detail]"); const tenantButton = event.target.closest?.("[data-platform-audit-tenant]"); if (event.target.closest?.("[data-platform-audit-order]")) { state.order = state.order === "desc" ? "asc" : "desc"; render(); } if (event.target.closest?.("[data-platform-audit-export]")) exportCsv(); if (tenantButton) window.showScreen?.("platform"); if (detailButton) { const item = state.events.find((eventItem) => eventItem.id === detailButton.dataset.platformAuditDetail); if (item) window.showToast?.(`${item.targetId} · ${detail(item)}`); } });
  window.addEventListener("platform-audit-reference", (event) => { state.filters.reference = event.detail || ""; render(); });
  window.addEventListener("role-session-applied", () => setTimeout(load, 0)); window.addEventListener("platform-overview-loaded", () => setTimeout(load, 0)); window.addEventListener("hashchange", () => { if (location.hash === "#view-audit") load(); }); setTimeout(load, 0);
})();
